\newcommand{\sgn}{\operatorname{sign}}

\title{The M\"obius Discriminant: A Scalar Invariant Governing Log-Convexity, Tur\'an Inequalities, and Hankel Dynamics of Recurrence Sequences}
\author{Aristotle}
\date{2026-07-14}

\begin{document}

\begin{abstract}
We study the family of \emph{first-order multiplicative recurrences}
$(\alpha n + \beta)\,a(n+1) = (\gamma n + \delta)\,a(n)$, whose step multiplier
$(\gamma n + \delta)/(\alpha n + \beta)$ is a M\"obius (linear-fractional) function of the index.
We isolate a single scalar invariant, the \emph{M\"obius discriminant} $\Delta = \gamma\beta - \alpha\delta$,
and show that its sign controls the global qualitative behaviour of every positive solution.
We prove: an exact forward-difference identity expressing the change in the consecutive-ratio sequence
as $\Delta$ over a product of denominators; strict monotonicity of the ratio sequence $n \mapsto a(n+1)/a(n)$
determined by $\sgn(\Delta)$; all-order Tur\'an inequalities $a(i+1)a(j) < a(i)a(j+1)$ for all $i < j$
when $\Delta > 0$ (reversed when $\Delta < 0$), i.e.\ global log-convexity/concavity across arbitrary
index gaps; and the exact telescoping-product closed form
$a(n) = a(0)\prod_{k<n}(\gamma k + \delta)/(\alpha k + \beta)$. We then treat the second-order
constant-coefficient recurrence $p\,a(n+2) = q\,a(n+1) + r\,a(n)$ and prove that the pointwise Hankel
determinant $D(n) = a(n)a(n+2) - a(n+1)^2$ obeys the exact first-order law $p\,D(n+1) = -r\,D(n)$,
with geometric closed form $p^n D(n) = (-r)^n D(0)$. The middle coefficient $q$ cancels, isolating
$r/p$ as the curvature multiplier: $r/p > 0$ forces perpetual sign alternation, $r/p < 0$ eventual
sign constancy. Cassini's identity for Fibonacci emerges as the special case $p = r = 1$.
\end{abstract}

\maketitle

\section{Introduction}

A large number of sequences arising in combinatorics, special-function theory, and analysis are
generated by a rule in which each term is a rational multiple of its predecessor, with multiplier
a ratio of two affine functions of the index. Factorials, binomial coefficients along a row,
Catalan numbers, central binomial coefficients, and general hypergeometric term sequences all
satisfy a recurrence of the form
\begin{equation}
(\alpha n + \beta)\,a(n+1) = (\gamma n + \delta)\,a(n). \tag{1}
\end{equation}
The multiplier $m(n) = (\gamma n + \delta)/(\alpha n + \beta)$ is a linear-fractional (M\"obius)
function of $n$; we attach to (1) the scalar
\[
\Delta = \gamma\beta - \alpha\delta = \det\begin{pmatrix} \gamma & \delta \\ \alpha & \beta \end{pmatrix},
\]
the \emph{M\"obius discriminant}, the cross-difference of the numerator and denominator coefficients.
When $\Delta = 0$ the two lines are proportional, $m$ is constant, and (1) generates a geometric
sequence; the interesting regime is $\Delta \neq 0$. We show that $\Delta$ is a complete qualitative
invariant for the log-behaviour of solutions of (1), and that the sign dynamics of the Hankel
determinant of a constant-coefficient second-order recurrence is governed by an equally simple
first-order law with the ratio $r/p$ in the role of $\Delta$.

Throughout we work with real sequences and assume denominators positive on the relevant range,
as holds for the classical examples.

\section{The forward-difference identity}

\noindent\textbf{Standing hypotheses (H).} Fix $\alpha,\beta,\gamma,\delta \in \R$ and a sequence
$a : \N \to \R$ with, for all $n$: $a(n) > 0$, $\alpha n + \beta > 0$, and
$(\alpha n + \beta)\,a(n+1) = (\gamma n + \delta)\,a(n)$.

\begin{lemma}[Ratio equals M\"obius datum]\label{lem:ratio}
Under \textup{(H)}, for every $n$, $\dfrac{a(n+1)}{a(n)} = \dfrac{\gamma n + \delta}{\alpha n + \beta}$.
\end{lemma}
\begin{proof}
Divide the recurrence by $(\alpha n + \beta)\,a(n) > 0$.
\end{proof}

\begin{theorem}[Forward-difference identity]\label{thm:fd}
Under \textup{(H)}, for every $n$,
\[
\frac{a(n+2)}{a(n+1)} - \frac{a(n+1)}{a(n)} = \frac{\Delta}{(\alpha n + \beta)\,\big(\alpha(n+1) + \beta\big)},
\qquad \Delta = \gamma\beta - \alpha\delta.
\]
\end{theorem}
\begin{proof}
By Lemma~\ref{lem:ratio} the left side is
$\frac{\gamma(n+1)+\delta}{\alpha(n+1)+\beta} - \frac{\gamma n+\delta}{\alpha n+\beta}$.
Over the common denominator $(\alpha n+\beta)(\alpha(n+1)+\beta)$ the numerator is
$(\gamma(n+1)+\delta)(\alpha n+\beta) - (\gamma n+\delta)(\alpha(n+1)+\beta)$; expanding, the
quadratic and linear terms in $n$ cancel, leaving $\gamma\beta - \alpha\delta = \Delta$.
\end{proof}

The denominator is a product of two positive quantities, so the sign of the forward difference
equals $\sgn(\Delta)$.

\section{Monotone ratios}

\begin{theorem}[Monotone growth factor]\label{thm:mono}
Assume \textup{(H)}. If $\Delta > 0$ then $n \mapsto a(n+1)/a(n)$ is strictly increasing on $\N$;
if $\Delta < 0$ it is strictly decreasing on $\N$.
\end{theorem}
\begin{proof}
A real sequence increasing (resp.\ decreasing) at every step is strictly monotone. By
Theorem~\ref{thm:fd} the step difference is $\Delta$ over a strictly positive denominator, hence
strictly positive when $\Delta>0$ and strictly negative when $\Delta<0$.
\end{proof}

\section{All-order Tur\'an inequalities}

\begin{theorem}[All-order Tur\'an inequalities]\label{thm:turan}
Assume \textup{(H)} and let $i < j$. If $\Delta > 0$ then $a(i+1)\,a(j) < a(i)\,a(j+1)$;
if $\Delta < 0$ then $a(i)\,a(j+1) < a(i+1)\,a(j)$.
\end{theorem}
\begin{proof}
For $\Delta>0$, Theorem~\ref{thm:mono} gives $a(i+1)/a(i) < a(j+1)/a(j)$; multiplying by
$a(i)a(j) > 0$ yields $a(i+1)a(j) < a(i)a(j+1)$. The case $\Delta<0$ is identical with the
inequality reversed.
\end{proof}

Specializing to $j = i+1$ recovers $a(i+1)^2 < a(i)a(i+2)$; the general statement expresses
log-convexity uniformly across arbitrary gaps.

\section{The telescoping product}

\begin{theorem}[Closed form]\label{thm:prod}
Assume \textup{(H)}. For every $n$,
$\displaystyle a(n) = a(0)\,\prod_{k=0}^{n-1} \frac{\gamma k + \delta}{\alpha k + \beta}$.
\end{theorem}
\begin{proof}
Induction on $n$: the base $n=0$ is the empty product; for the step, Lemma~\ref{lem:ratio} gives
$a(m+1) = a(m)\cdot\frac{\gamma m+\delta}{\alpha m+\beta}$, and substituting the inductive hypothesis
appends the factor $k=m$.
\end{proof}

When $\alpha,\gamma > 0$, standard estimates give
$a(n) \sim C\,(\gamma/\alpha)^n\, n^{\,\delta/\gamma - \beta/\alpha}$: exponential rate $\gamma/\alpha$
and polynomial correction set by the secondary M\"obius datum $\delta/\gamma - \beta/\alpha$.

\medskip\noindent\textbf{Example (Catalan).} The recurrence $(n+2)C(n+1) = (4n+2)C(n)$ has
$\alpha=1,\beta=2,\gamma=4,\delta=2$, so $\Delta = 8 - 2 = 6 > 0$; the growth factors
$2(2n+1)/(n+2) = 1, 2, 2.5, 2.8, \dots \nearrow 4$ increase as Theorem~\ref{thm:mono} predicts.

\section{Second order: the Hankel law}

\begin{definition}
For $a:\N\to\R$, the \emph{Hankel determinant} is $D(n) = a(n)\,a(n+2) - a(n+1)^2$.
\end{definition}

\begin{theorem}[Hankel recurrence]\label{thm:hankel}
Let $p,q,r \in \R$ and suppose $p\,a(n+2) = q\,a(n+1) + r\,a(n)$ for all $n$. Then
$p\,D(n+1) = -r\,D(n)$ for all $n$; the coefficient $q$ does not appear.
\end{theorem}
\begin{proof}
Expand $p\,D(n+1) = p\,a(n+1)a(n+3) - p\,a(n+2)^2$ and substitute
$p\,a(n+3) = q\,a(n+2)+r\,a(n+1)$ and $p\,a(n+2) = q\,a(n+1)+r\,a(n)$. The $q$-terms cancel,
leaving $-r\big(a(n)a(n+2) - a(n+1)^2\big) = -r\,D(n)$. This is the combination
$a(n+1)\cdot[\mathrm{rec}(n+1)] - a(n+2)\cdot[\mathrm{rec}(n)]$.
\end{proof}

\begin{theorem}[Geometric closed form]\label{thm:hankelcf}
Under the hypotheses of Theorem~\ref{thm:hankel}, $p^n\,D(n) = (-r)^n\,D(0)$ for all $n$.
\end{theorem}
\begin{proof}
Induction: $p^{k+1}D(k+1) = p^k(p\,D(k+1)) = p^k(-r\,D(k)) = -r(-r)^k D(0) = (-r)^{k+1}D(0)$.
\end{proof}

\begin{theorem}[Nonvanishing]\label{thm:nz}
If $r \neq 0$ and $D(0) \neq 0$, then $D(n) \neq 0$ for all $n$.
\end{theorem}
\begin{proof}
$D(n)=0$ would force $(-r)^n D(0) = 0$ by Theorem~\ref{thm:hankelcf}, impossible.
\end{proof}

\begin{theorem}[Sign alternation]\label{thm:alt}
If $p>0$, $r>0$, and $D(0)\neq 0$, then $D(n+1)D(n) < 0$ for all $n$; hence $D$ is positive
at infinitely many indices and negative at infinitely many indices, never eventually one-signed.
\end{theorem}
\begin{proof}
By Theorem~\ref{thm:nz}, $D(n)\neq 0$; by Theorem~\ref{thm:hankel},
$D(n+1)D(n) = (-r/p)D(n)^2$ with $D(n)^2>0$ and $-r/p<0$, a negative product. Sign opposition
at every step precludes eventual one-signedness.
\end{proof}

\begin{corollary}[Curvature dichotomy]
For $p\,a(n+2) = q\,a(n+1) + r\,a(n)$ with $D(0)\neq 0$: if $r/p<0$ the sign of $D(n)$ is
eventually constant; if $r/p>0$ it alternates forever.
\end{corollary}

\begin{corollary}[Cassini]
For Fibonacci ($p=q=r=1$, $D(0)=-1$), Theorem~\ref{thm:hankelcf} gives
$F(n)F(n+2) - F(n+1)^2 = (-1)^{n+1}$, whose sign alternates forever by Theorem~\ref{thm:alt}
($r/p = 1 > 0$).
\end{corollary}

\section{Discussion and future work}

Both halves share a philosophy: the qualitative log-behaviour of a recurrence sequence is
controlled by one scalar per order --- $\Delta = \gamma\beta - \alpha\delta$ in first order,
the ratio $r/p$ in second order. Apparent chaos (Cassini's oscillation) is a geometric sequence
with a negative ratio. Directions: (i) a curvature dichotomy across order, conjecturing the
order-$k$ Casoratian is geometric with ratio $(-1)^{k-1}r/p$; (ii) $\Delta$ as a complete
invariant, with the converse implications from any single Tur\'an inequality back to $\sgn(\Delta)$;
(iii) sharp two-term asymptotics with explicit constants from the telescoping product.

