algorithms.pseudocode:
function telescoping_terms(alpha, beta, gamma, delta, a0, N):
    terms <- [a0]; running <- a0
    for k in 0 .. N-2:
        running <- running * (gamma*k+delta)/(alpha*k+beta)
        append running to terms
    return terms
